def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = item / np.maximum(bins, 1e-9)
    score = -10.0 * np.maximum(0.0, remaining) - 1.0 / (np.abs(fill_ratio - 0.6) + 1e-3)
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining < 0, -np.inf, -remaining)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    ratio = item / np.where(bins > 0, bins, np.inf)
    return np.where(remaining < 0, -np.inf, -1.0 / (remaining + 1e-9) + ratio)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = item / np.maximum(bins, 1e-9)
    score = -((fill_ratio - 0.7) ** 2) - np.exp(-remaining + 1e-9)
    return np.where(remaining < 0, -np.inf, score)
